export function geteilteMenge(erzeugung, verbrauch, a) {
  if (verbrauch <= 0 || erzeugung <= 0) return 0;
  const R = erzeugung / verbrauch;
  return verbrauch * a * (1 - Math.exp(-R / a));
}

